function courierEditorV2(c,index){modalFormV2(c?'Edit courier':'Add courier',[['Courier code','code'],['Courier name','name'],['Account number','account'],['Services','services'],['Allocation priority','priority','number'],['Status','status','select',['Active','Disabled']],['COD enabled','cod','checkbox'],['Tracking API','tracking','checkbox'],['Label API','label','checkbox'],['API base URL','api'],['API username','username'],['API key / token','token','password']],d=>{const record={...d,priority:Number(d.priority),cod:!!d.cod,tracking:!!d.tracking,label:!!d.label};if(c)adminData.couriers[index]=record;else adminData.couriers.push(record);saveAdmin('sc_admin_couriers',adminData.couriers);auditV2(c?'Updated courier':'Added courier','Configuration',d.name);couriersV2()},c)}
function serviceabilityV2(zoneMode=false){const rows=state.zones;$('#adminContent').innerHTML=pageHead('CONFIGURATION',zoneMode?'Zone Management':'Serviceability',zoneMode?'Create zones and map states, cities and pincodes.':'Control pickup/delivery availability, COD, TAT and ODA at pincode level.',`<input id="servicePin" maxlength="6" placeholder="Check PIN code"><button class="button teal" id="serviceCheck">Check</button><button class="button ghost" id="exportPins">Export pincodes</button><button class="button" id="importPins">Import mapping</button>`)+`<section class="admin-stat-grid">${stat('SERVICEABLE PINS','27,458','⌖','#168b83','#e4f6f3','Pickup or delivery')}${stat('COD PINS','21,384','₹','#347f9b','#e7f2f7','Cash on delivery')}${stat('ODA PINS','4,186','!','#d88b23','#fff1dc','Remote surcharge')}${stat('ACTIVE ZONES',rows.filter(z=>z.status==='Active').length,'◇','#7b5ca2','#f1ebf8','Rate zones')}</section><article class="admin-card recent-card"><div class="admin-table-wrap"><table class="data-table admin-table"><thead><tr><th>ZONE</th><th>DESCRIPTION</th><th>PIN CODES</th><th>COURIERS</th><th>PICKUP</th><th>DELIVERY</th><th>COD</th><th>ODA</th><th>TAT</th><th>ACTION</th></tr></thead><tbody>${rows.map((z,i)=>`<tr><td><b>Zone ${z.code}</b></td><td>${z.name}</td><td>${z.pins}</td><td>${z.couriers}</td><td>✓</td><td>✓</td><td>${z.oda==='Yes'?'Limited':'✓'}</td><td>${z.oda}</td><td>${i+1}–${i+3} days</td><td><button class="small-action secondary" data-zone-edit="${i}">Edit</button></td></tr>`).join('')}</tbody></table></div></article>`;$('#serviceCheck').onclick=()=>{const p=$('#servicePin').value;if(!/^\d{6}$/.test(p))return toast('Enter a valid 6-digit PIN.','error');modal(`<small class="live-pill">SERVICEABILITY</small><h2 class="modal-title">${p} is serviceable</h2><div class="detail-grid"><div><span>ZONE</span><b>Zone C</b></div><div><span>PICKUP</span><b>Available</b></div><div><span>DELIVERY</span><b>Available</b></div><div><span>COD</span><b>Available</b></div><div><span>ODA</span><b>No</b></div><div><span>COURIERS</span><b>${adminData.couriers.filter(c=>c.status==='Active').length}</b></div></div>`)};$('#exportPins').onclick=()=>download('serviceability-zones.csv',[['Zone','Name','Pincodes','Couriers','ODA','Status'],...rows.map(Object.values)]);$('#importPins').onclick=()=>importModalV2('Serviceability mapping');$$('[data-zone-edit]').forEach(b=>b.onclick=()=>zoneEditorV2(rows[+b.dataset.zoneEdit],+b.dataset.zoneEdit))}
function zoneEditorV2(z,index){modalFormV2('Edit zone',[['Zone code','code'],['Zone name','name'],['Pincode count','pins'],['Courier count','couriers','number'],['ODA','oda','select',['No','Yes','Mixed']],['Status','status','select',['Active','Review','Disabled']]],d=>{state.zones[index]={...d,couriers:Number(d.couriers)};saveAdmin('sc_admin_zones',state.zones);auditV2('Updated zone','Serviceability',d.code);serviceabilityV2(true)},z)}
function pricingV2(type){const rows=state.rates.filter(r=>r.type===type);$('#adminContent').innerHTML=pageHead('CONFIGURATION',`${type} Pricing`,`Set ${type} seller rates by courier, zone, service, payment mode and weight slab.`,`<button class="button ghost" id="exportRateV2">Export rates</button><button class="button ghost" id="importRateV2">Import rates</button><button class="button" id="addRateV2">+ Add ${type} rate</button>`)+`<section class="admin-stat-grid">${stat('RATE CARDS',rows.length,type[0],'#168b83','#e4f6f3',`${type} pricing tables`)}${stat('COURIERS',new Set(rows.map(r=>r.courier)).size,'⇄','#347f9b','#e7f2f7','Configured in rates')}${stat('CHARGE TYPES',adminData.charges.length,'₹','#d88b23','#fff1dc','Additional calculations')}</section><article class="admin-card recent-card">${rateTable(rows)}</article>`;$('#exportRateV2').onclick=()=>download(`${type.toLowerCase()}-rates.csv`,[['ID','Type','Courier','Service','Zone','Weight','Rate','Status'],...rows.map(Object.values)]);$('#importRateV2').onclick=()=>importModalV2(`${type} rate card`);$('#addRateV2').onclick=()=>rateEditorV2(type)}
function rateEditorV2(type){modalFormV2(`Add ${type} rate slab`,[['Courier','courier','select',adminData.couriers.map(c=>c.name)],['Service','service','select',['Surface','Express','Air']],['Origin zone','origin','select',state.zones.map(z=>'Zone '+z.code)],['Destination zone','zone','select',state.zones.map(z=>'Zone '+z.code)],['Payment mode','payment','select',['Prepaid','COD','To Pay']],['Weight from (kg)','from','number'],['Weight to (kg)','to','number'],['Base rate','rate','number'],['Additional / kg','additional','number'],['Minimum charge','minimum','number'],['Fuel %','fuel','number'],['COD charge','cod','number']],d=>{state.rates.unshift({id:`RT-${type}-${String(Date.now()).slice(-4)}`,type,courier:d.courier,service:d.service,zone:`${d.origin} → ${d.zone}`,weight:`${d.from}–${d.to} kg`,rate:Number(d.rate),payment:d.payment,additional:d.additional,minimum:d.minimum,fuel:d.fuel,cod:d.cod,status:'Active'});saveAdmin('sc_admin_rates',state.rates);auditV2('Created rate slab','Pricing',`${type} / ${d.courier}`);pricingV2(type)})}
function chargesV2(){const rows=adminData.charges;$('#adminContent').innerHTML=pageHead('CONFIGURATION','Additional Charges','Configure fuel, COD, ODA, RTO, insurance, handling and custom surcharges.',`<button class="button" id="addCharge">+ Add charge type</button>`)+`<article class="admin-card"><div class="admin-table-wrap"><table class="data-table admin-table"><thead><tr><th>CODE</th><th>CHARGE NAME</th><th>APPLIES TO</th><th>METHOD</th><th>VALUE</th><th>MINIMUM</th><th>GST</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td><b>${r.code}</b></td><td>${r.name}</td><td>${r.applies}</td><td>${r.method}</td><td>${r.value}</td><td>${money(r.min)}</td><td>${r.tax?'Yes':'No'}</td><td><span class="status-badge delivered">${r.status}</span></td><td><button class="small-action secondary" data-charge-edit="${i}">Edit</button></td></tr>`).join('')}</tbody></table></div></article>`;$('#addCharge').onclick=()=>chargeEditorV2();$$('[data-charge-edit]').forEach(b=>b.onclick=()=>chargeEditorV2(rows[+b.dataset.chargeEdit],+b.dataset.chargeEdit))}
function chargeEditorV2(c,index){modalFormV2(c?'Edit charge':'Add charge',[['Charge code','code'],['Charge name','name'],['Applies to','applies','select',['Freight','COD orders','ODA pincodes','RTO orders','All shipments']],['Calculation method','method','select',['Flat','Percentage','Per kg','Higher of flat or %','Freight multiplier']],['Value / formula','value'],['Minimum charge','min','number'],['GST applicable','tax','checkbox'],['Status','status','select',['Active','Inactive']]],d=>{const record={...d,min:Number(d.min),tax:!!d.tax};if(c)rows[index]=record;else rows.push(record);saveAdmin('sc_admin_charges',rows);auditV2(c?'Updated charge':'Added charge','Pricing',d.code);chargesV2()},c)}
function allocationV2(){const rows=adminData.rules;$('#adminContent').innerHTML=pageHead('CONFIGURATION','Allocation Rules','Auto-select couriers by cost, SLA, serviceability, success rate and priority.',`<button class="button" id="addRule">+ Add allocation rule</button>`)+`<article class="admin-card">${simpleTable(['RULE','CONDITION','STRATEGY','PRIORITY','STATUS'],rows.map(r=>[r.name,r.condition,r.strategy,'L'+r.priority,r.status]))}</article>`;$('#addRule').onclick=()=>modalFormV2('Create allocation rule',[['Rule name','name'],['Condition','condition'],['Selection strategy','strategy','select',['Lowest landed cost','Fastest TAT','Highest success rate','Courier priority','Balanced score']],['Priority','priority','number'],['Status','status','select',['Active','Inactive']]],d=>{rows.push({...d,priority:Number(d.priority)});saveAdmin('sc_admin_rules',rows);allocationV2()})}
function rateCalculatorV2(){$('#adminContent').innerHTML=pageHead('TOOLS','Rate Calculator','Compare landed cost and TAT across all serviceable couriers.')+`<form class="admin-card form-grid" id="rateCalc"><div class="form-field"><label>Pickup PIN</label><input name="from" maxlength="6" required></div><div class="form-field"><label>Delivery PIN</label><input name="to" maxlength="6" required></div><div class="form-field"><label>Weight (kg)</label><input name="weight" type="number" step=".1" required></div><div class="form-field"><label>Payment mode</label><select name="payment"><option>Prepaid</option><option>COD</option></select></div><div class="form-field"><label>COD / invoice value</label><input name="value" type="number"></div><div class="form-field"><label>Business model</label><select name="model"><option>B2C</option><option>B2B</option></select></div><div class="form-actions"><button class="button" type="submit">Calculate rates</button></div></form><div id="rateCalcResults" class="recent-card"></div>`;$('#rateCalc').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));if(!/^\d{6}$/.test(d.from)||!/^\d{6}$/.test(d.to))return toast('Enter valid pickup and delivery PIN codes.','error');$('#rateCalcResults').innerHTML=`<article class="admin-card"><div class="admin-card-head"><div><small>AVAILABLE SERVICES</small><b>${d.from} → ${d.to} · ${d.weight} kg</b></div></div><div class="rate-results">${adminData.couriers.filter(c=>c.status==='Active').map((c,i)=>`<div><span class="client-avatar">${c.code[0]}</span><b>${c.name}<small>${i%2?'Surface':'Express'} · ${i+1}–${i+3} days</small></b><em>${i===0?'Best price':i===1?'Fastest':'Available'}</em><strong>${money(79+i*26+Number(d.weight)*12)}</strong><button data-label-download="RATE">Select</button></div>`).join('')}</div></article>`;v2Actions()}}
function reportsV2(page){const orders=state.shipments,revenue=orders.reduce((a,o)=>a+Number(String(o.amount||0).replace(/[^0-9.]/g,'')),0);$('#adminContent').innerHTML=pageHead('ANALYTICS',page,'Filter, analyze and export operational performance.',`<input type="date" value="${new Date(Date.now()-30*864e5).toISOString().slice(0,10)}"><input type="date" value="${new Date().toISOString().slice(0,10)}"><select><option>All sellers</option>${clients().filter(c=>!c.placeholder).map(c=>`<option>${esc(c.name)}</option>`).join('')}</select><button class="button ghost" id="reportExport">Export CSV</button>`)+`<section class="admin-stat-grid">${stat('TOTAL ORDERS',orders.length,'◇','#347f9b','#e7f2f7','Selected period')}${stat('GROSS REVENUE',money(revenue),'₹','#168b83','#e4f6f3','Before adjustments')}${stat('AVG ORDER VALUE',money(orders.length?revenue/orders.length:0),'↗','#7b5ca2','#f1ebf8','Revenue per shipment')}${stat('DELIVERED',orders.filter(o=>o.status==='Delivered').length,'✓','#249465','#e5f7ee','Completed orders')}</section><section class="admin-grid"><article class="admin-card"><div class="admin-card-head"><div><small>PERFORMANCE TREND</small><b>${page}</b></div></div><div class="trend-chart tall">${[22,31,25,48,43,61,54,72,66,88,79,95].map(h=>`<i style="height:${h}%"></i>`).join('')}</div></article><article class="admin-card"><div class="admin-card-head"><div><small>COURIER SHARE</small><b>Allocation</b></div></div>${courierBars()}</article></section><article class="admin-card recent-card">${ordersTableV2(orders)}</article>`;$('#reportExport').onclick=()=>download(`${page.toLowerCase().replaceAll(' ','-')}.csv`,[['Order','AWB','Seller','Courier','Destination','Status','Amount'],...orders.map(o=>[o.orderId,o.awb,o.client,o.carrier,o.destination,o.status,o.amount])]);v2Actions()}
function cmsV2(){const c=state.content,extras=read('sc_site_extras',{announcement:'Ship smarter with SearchCraft Digital',navCta:'Free Sign Up',featureTitle:'Powerful without feeling complicated.',supportEmail:'support@searchcraft.in',supportPhone:'+91 99999 99999',seoTitle:'SearchCraft Digital — Ship smarter. Scale faster.',seoDescription:'Modern courier aggregation, tracking and billing platform.',showCarriers:true,showFeatures:true,showReviews:true,showFaq:true});$('#adminContent').innerHTML=pageHead('MARKETING','Landing Page Control','Control hero, navigation, sections, announcement, SEO, contact details and visibility.',`<a class="button ghost" href="../" target="_blank">Open live page ↗</a>`)+`<div class="cms-layout"><form class="admin-card cms-editor" id="cmsV2"><div class="cms-tabs"><button type="button" class="active">Hero</button><button type="button">Sections</button><button type="button">SEO</button><button type="button">Footer</button></div><section class="cms-section"><h3>Announcement & navigation</h3><div class="cms-fields"><label class="wide">Announcement bar<input name="announcement" value="${esc(extras.announcement)}"></label><label>Navigation CTA<input name="navCta" value="${esc(extras.navCta)}"></label><label>Hero eyebrow<input name="heroEyebrow" value="${esc(c.heroEyebrow)}"></label></div></section><section class="cms-section"><h3>Hero section</h3><div class="cms-fields"><label>Headline<input name="heroTitle" value="${esc(c.heroTitle)}"></label><label>Accent line<input name="heroAccent" value="${esc(c.heroAccent)}"></label><label class="wide">Description<textarea name="heroLead">${esc(c.heroLead)}</textarea></label><label>Primary button<input name="heroPrimary" value="${esc(c.heroPrimary)}"></label><label>Secondary button<input name="heroSecondary" value="${esc(c.heroSecondary)}"></label></div></section><section class="cms-section"><h3>Homepage sections</h3><div class="cms-fields"><label class="wide">Features heading<input name="featureTitle" value="${esc(extras.featureTitle)}"></label></div><div class="visibility-grid">${[['showCarriers','Carrier ecosystem',extras.showCarriers],['showFeatures','Features',extras.showFeatures],['showReviews','Customer reviews',extras.showReviews],['showFaq','FAQs',extras.showFaq]].map(x=>`<label><input type="checkbox" name="${x[0]}" ${x[2]?'checked':''}> ${x[1]}</label>`).join('')}</div></section><section class="cms-section"><h3>Final CTA & footer</h3><div class="cms-fields"><label>CTA eyebrow<input name="ctaEyebrow" value="${esc(c.ctaEyebrow)}"></label><label>CTA headline<input name="ctaTitle" value="${esc(c.ctaTitle)}"></label><label class="wide">CTA description<textarea name="ctaText">${esc(c.ctaText)}</textarea></label><label>CTA button<input name="ctaButton" value="${esc(c.ctaButton)}"></label><label>Footer strapline<input name="footerText" value="${esc(c.footerText)}"></label><label>Support email<input name="supportEmail" value="${esc(extras.supportEmail)}"></label><label>Support phone<input name="supportPhone" value="${esc(extras.supportPhone)}"></label></div></section><section class="cms-section"><h3>Search engine settings</h3><div class="cms-fields"><label class="wide">SEO title<input name="seoTitle" value="${esc(extras.seoTitle)}"></label><label class="wide">Meta description<textarea name="seoDescription">${esc(extras.seoDescription)}</textarea></label></div></section><div class="admin-actions"><button class="button teal" type="button" id="cmsDraftV2">Save draft</button><button class="button" type="submit">Publish website</button></div></form><aside class="preview-browser"><div class="preview-top"><i></i><i></i><i></i></div><div class="preview-screen"><small id="pvEyebrow">${esc(c.heroEyebrow)}</small><h2><span id="pvTitle">${esc(c.heroTitle)}</span><br><span id="pvAccent">${esc(c.heroAccent)}</span></h2><p id="pvLead">${esc(c.heroLead)}</p><button id="pvButton">${esc(c.heroPrimary)}</button></div></aside></div>`;const form=$('#cmsV2'),collect=()=>Object.fromEntries(new FormData(form));form.oninput=()=>{$('#pvEyebrow').textContent=form.heroEyebrow.value;$('#pvTitle').textContent=form.heroTitle.value;$('#pvAccent').textContent=form.heroAccent.value;$('#pvLead').textContent=form.heroLead.value;$('#pvButton').textContent=form.heroPrimary.value};form.onsubmit=e=>{e.preventDefault();const d=collect(),base={};['heroEyebrow','heroTitle','heroAccent','heroLead','heroPrimary','heroSecondary','ctaEyebrow','ctaTitle','ctaText','ctaButton','footerText'].forEach(k=>base[k]=d[k]);const extra={...d,showCarriers:form.showCarriers.checked,showFeatures:form.showFeatures.checked,showReviews:form.showReviews.checked,showFaq:form.showFaq.checked};localStorage.setItem('sc_site_content',JSON.stringify(base));localStorage.setItem('sc_site_extras',JSON.stringify(extra));auditV2('Published landing page','Marketing','Homepage content');toast('Landing page published successfully.')};$('#cmsDraftV2').onclick=()=>{localStorage.setItem('sc_site_draft_v2',JSON.stringify(collect()));toast('Website draft saved.')}}
function marketingV2(page){if(page==='Landing Page Control'){cmsV2();return}const map={'Banners & Announcements':{store:'sc_admin_notices',rows:adminData.notices,fields:[['Title','title'],['Message','message'],['Placement','placement','select',['Homepage top','Dashboard','Login page']],['Start date','start','date'],['End date','end','date'],['Status','status','select',['Active','Scheduled','Inactive']]]},'Coupons':{store:'sc_admin_coupons',rows:adminData.coupons,fields:[['Coupon code','code'],['Description','description'],['Discount type','type','select',['Flat','Percentage']],['Value','value','number'],['Minimum recharge','minimum','number'],['Expiry','expiry','date'],['Usage limit','limit','number']]},'Notifications':{store:'sc_admin_notices',rows:adminData.notices,fields:[['Template name','title'],['Channel','placement','select',['Email','SMS','WhatsApp','Push']],['Trigger','start','select',['Order booked','Picked up','Out for delivery','Delivered','NDR','Wallet low']],['Message','message'],['Status','status','select',['Active','Inactive']]]}};const cfg=map[page];$('#adminContent').innerHTML=pageHead('MARKETING',page,`Create and manage ${page.toLowerCase()}.`,`<button class="button" id="addMarketing">+ Create</button>`)+`<article class="admin-card">${simpleTable(['NAME / CODE','DESCRIPTION','TYPE / PLACEMENT','STATUS / EXPIRY'],cfg.rows.map(x=>[x.title||x.code,x.message||x.description,x.placement||x.type,x.status||x.expiry]))}</article>`;$('#addMarketing').onclick=()=>modalFormV2(`Create ${page}`,cfg.fields,d=>{cfg.rows.unshift(d);saveAdmin(cfg.store,cfg.rows);auditV2(`Created ${page}`,'Marketing',d.title||d.code);marketingV2(page)})}
function settingsV2(page){if(page==='Audit Logs'){const rows=adminData.audit;$('#adminContent').innerHTML=pageHead('SYSTEM','Audit Logs','Every important admin change with user, module and timestamp.',`<button class="button ghost" id="auditExport">Export audit</button>`)+`<article class="admin-card">${simpleTable(['TIME','USER','ACTION','MODULE','DETAIL'],rows.map(x=>[x.time,x.user,x.action,x.module,x.detail]))}</article>`;$('#auditExport').onclick=()=>download('admin-audit-log.csv',[['Time','User','Action','Module','Detail'],...rows.map(Object.values)]);return}if(page==='Roles & Permissions'){teamPage();return}const isApi=page==='API & Webhooks';$('#adminContent').innerHTML=pageHead('SETTINGS',page,isApi?'Manage API access, callbacks and integration events.':'Configure platform identity, tax, billing and operational defaults.')+`<form class="admin-card form-grid two" id="settingsV2">${(isApi?[['API status','apiStatus','select',['Enabled','Disabled']],['Webhook URL','webhook'],['Webhook secret','secret','password'],['Events','events'],['Retry attempts','retries','number'],['IP whitelist','ips']]:[['Platform name','name'],['Support email','email','email'],['Support phone','phone'],['GSTIN','gstin'],['Default currency','currency','select',['INR','USD','AED']],['Timezone','timezone','select',['Asia/Kolkata','UTC']],['Invoice prefix','prefix'],['Low wallet threshold','threshold','number'],['Default volumetric divisor','divisor','number'],['Maintenance mode','maintenance','checkbox']]).map(f=>fieldHtmlV2(f)).join('')}<div class="form-actions"><button class="button" type="submit">Save settings</button></div></form>`;$('#settingsV2').onsubmit=e=>{e.preventDefault();localStorage.setItem(`sc_${isApi?'api':'platform'}_settings`,JSON.stringify(Object.fromEntries(new FormData(e.currentTarget))));auditV2('Updated settings','System',page);toast(`${page} saved.`)}}
function modalFormV2(title,fields,onSave,values={}){modal(`<h2 class="modal-title">${esc(title)}</h2><p class="modal-copy">Complete the fields below and save.</p><form class="form-grid two" id="v2ModalForm">${fields.map(f=>fieldHtmlV2(f,values[f[1]])).join('')}<div class="form-actions"><button type="button" class="button ghost" data-close-modal>Cancel</button><button class="button" type="submit">Save</button></div></form>`);$('[data-close-modal]',$('#modalBody')).onclick=closeModal;$('#v2ModalForm').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));fields.filter(f=>f[2]==='checkbox').forEach(f=>data[f[1]]=e.currentTarget.elements[f[1]].checked);closeModal();onSave(data)}}
function fieldHtmlV2(f,value=''){const [label,name,type='text',options=[]]=f;if(type==='select')return `<div class="form-field"><label>${label}</label><select name="${name}">${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`;if(type==='checkbox')return `<div class="form-field checkbox-field"><label><input type="checkbox" name="${name}" ${value?'checked':''}> ${label}</label></div>`;return `<div class="form-field"><label>${label}</label><input name="${name}" type="${type}" value="${esc(value)}" required></div>`}
function importModalV2(name){modal(`<h2 class="modal-title">Import ${esc(name)}</h2><div class="upload-zone"><span>⇩</span><h3>Choose CSV or XLSX</h3><p>Download the format first and validate before processing.</p><input type="file" id="v2ImportFile" accept=".csv,.xlsx,.xls"><button class="button" id="v2ProcessImport">Validate & import</button></div>`);$('#v2ProcessImport').onclick=()=>{if(!$('#v2ImportFile').files[0])return toast('Choose a file first.','error');auditV2(`Imported ${name}`,'Import',$('#v2ImportFile').files[0].name);closeModal();toast(`${name} imported successfully.`)}}
function adminNavigate(page,keep=false){const legacy={'Control Center':'Dashboard','Clients':'All Sellers','KYC Approvals':'KYC Verification','Wallet & Transactions':'Wallet Ledger','B2B / B2C Rates':'B2C Pricing','Zones & Serviceability':'Serviceability','Landing Page CMS':'Landing Page Control','Platform Settings':'General Settings'};page=legacy[page]||page;$('#pageCrumb').textContent=page;$$('[data-v2-page]').forEach(b=>b.classList.toggle('active',b.dataset.v2Page===page));$('#sidebar').classList.remove('open');const routes={Dashboard:dashboardV2,'All Orders':allOrdersV2,'Create Order':createOrderV2,'Bulk Order Import':bulkImportV2,'Labels & Manifests':labelCenterV2,'NDR & RTO':ndrV2,'Pickup Management':pickupsV2,'All Sellers':sellersV2,'KYC Verification':kycV2,'Seller Wallets':()=>financeV2('Seller Wallets'),'Rate Assignment':rateAssignmentV2,'Team & Roles':teamPage,'Support Tickets':()=>supportV2(false),'Weight Disputes':()=>supportV2(true),'Wallet Ledger':()=>financeV2('Wallet Ledger'),'COD & Settlements':()=>financeV2('COD & Settlements'),'Invoices & Billing':invoicesV2,'Credit Adjustments':()=>financeV2('Credit Adjustments'),'Sales & Revenue':()=>reportsV2('Sales & Revenue'),'Shipment Reports':()=>reportsV2('Shipment Reports'),'Courier Reports':()=>reportsV2('Courier Reports'),'GST Reports':()=>reportsV2('GST Reports'),'Rate Calculator':rateCalculatorV2,Couriers:couriersV2,'Service Providers':couriersV2,Serviceability:()=>serviceabilityV2(false),'Zone Management':()=>serviceabilityV2(true),'B2C Pricing':()=>pricingV2('B2C'),'B2B Pricing':()=>pricingV2('B2B'),'Additional Charges':chargesV2,'Allocation Rules':allocationV2,'Landing Page Control':cmsV2,'Banners & Announcements':()=>marketingV2('Banners & Announcements'),Coupons:()=>marketingV2('Coupons'),Notifications:()=>marketingV2('Notifications'),'General Settings':()=>settingsV2('General Settings'),'Roles & Permissions':()=>settingsV2('Roles & Permissions'),'API & Webhooks':()=>settingsV2('API & Webhooks'),'Audit Logs':()=>settingsV2('Audit Logs')};(routes[page]||dashboardV2)();if(!keep)history.replaceState(null,'',`#${encodeURIComponent(page)}`);scrollTo(0,0)}
renderV2Nav();$('#profileButton').onclick=()=>adminNavigate('General Settings');$('#globalSearch').onkeydown=e=>{if(e.key!=='Enter')return;const q=e.currentTarget.value.trim().toLowerCase();if(!q)return;const seller=clients().find(c=>Object.values(c).join(' ').toLowerCase().includes(q));if(seller&&!seller.placeholder)client360V2(seller);else{adminNavigate('All Orders');setTimeout(()=>{$('#v2OrderSearch').value=q;$('#v2OrderSearch').dispatchEvent(new Event('input'))})}};adminNavigate(decodeURIComponent(location.hash.slice(1)||'Dashboard'),true);addEventListener('hashchange',()=>adminNavigate(decodeURIComponent(location.hash.slice(1)||'Dashboard'),true));
